  {"slug":"viviz","kind":"group","end_year":null,"photos":[{"slot":1,"status":"approved","source":"commons","page":"https://commons.wikimedia.org/wiki/File:230315_VIVIZ_Seoul_Fashion_Week.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/2/2f/230315_VIVIZ_Seoul_Fashion_Week.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","width":4596,"height":2793,"sha1":"5131c85ad3d2b6728795fee9505b0b56c5170218","author":"K-POPIT 케이팝잇","author_url":"https://www.youtube.com/channel/UCY9QGuU9mBLBp_OCRNKeVSw","licence":"CC BY 3.0","licence_url":"https://creativecommons.org/licenses/by/3.0","share_alike":false,"date":"2023-03-15","date_precision":"day","event":"Seoul Fashion Week, Seoul, 15 March 2023","stage":false,"quality":4,"fx":50,"fy":50,"source_path":"images/group-photos/viviz.jpg","news_only":false,"review":""},{"slot":2,"status":"auto","source":"commons","page":"https://commons.wikimedia.org/wiki/File:VIVIZ_at_Billboard_K_POWER_100,_27_August_2024_04.png","url":"https://upload.wikimedia.org/wikipedia/commons/e/e1/VIVIZ_at_Billboard_K_POWER_100%2C_27_August_2024_04.png?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=original","width":3840,"height":2160,"sha1":"9b695a14c66b1c5e8782a4c698893f28c2ac8f28","author":"K-POPIT 케이팝잇","author_url":"https://www.youtube.com/channel/UCY9QGuU9mBLBp_OCRNKeVSw","licence":"CC BY 3.0","licence_url":"https://creativecommons.org/licenses/by/3.0","share_alike":false,"date":"2024-08-27","date_precision":"day","event":"Billboard K Power 100 event, Seoul","stage":false,"quality":4,"fx":50,"fy":45,"source_path":null,"news_only":false,"review":""},{"slot":3,"status":"auto","source":"commons","page":"https://commons.wikimedia.org/wiki/File:VIVIZ_(%EB%B9%84%EB%B9%84%EC%A7%80)_%EB%AE%A4%EC%A7%81%EB%B1%85%ED%81%AC_%EC%B6%9C%EA%B7%BC%EA%B8%B8_VIVIZ_Music_Bank_(4K)_0-48_screenshot.jpg","url":"https://upload.wikimedia.org/wikipedia/commons/f/f1/VIVIZ_%28%EB%B9%84%EB%B9%84%EC%A7%80%29_%EB%AE%A4%EC%A